gb2U(){return"Innehavstid och vanor"},
gb2V(){return"Importera transaktioner"},
gb2W(){return"Avkastning och utveckling"},
gb2X(){return"Portf\xf6ljens f\xf6rdelning"},
gb2Y(){return"Portf\xf6lj och innehav"},
